<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateSnippet\Domain;

use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\ValueObject\TemplateSnippetUidVO;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\ValueObject\TemplateSnippetCodeVO;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\ValueObject\Accessor\TemplateSnippetCodeAccessor;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\ValueObject\TemplateSnippetTenantVO;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\ValueObject\Accessor\TemplateSnippetTenantAccessor;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\ValueObject\TemplateSnippetContentHtmlVO;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\ValueObject\Accessor\TemplateSnippetContentHtmlAccessor;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\ValueObject\TemplateSnippetEnabledVO;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\ValueObject\Accessor\TemplateSnippetEnabledAccessor;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\ValueObject\TemplateSnippetVersionVO;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\ValueObject\Accessor\TemplateSnippetVersionAccessor;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\Formula\EnabledCalculator;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\Event\TemplateSnippetCreateEvent;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\Event\TemplateSnippetUpdateEvent;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\Event\TemplateSnippetDeleteEvent;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\Event\TemplateSnippetEnableEvent;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\Event\TemplateSnippetDisableEvent;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;

class TemplateSnippet extends TemplateSnippetRef
{
    use TemplateSnippetCodeAccessor;
    use TemplateSnippetTenantAccessor;
    use TemplateSnippetContentHtmlAccessor;
    use TemplateSnippetEnabledAccessor;
    use TemplateSnippetVersionAccessor;
    private array $recordedEvents = [];

    public function __construct(
        TemplateSnippetUidVO|string $uid,
        TemplateSnippetCodeVO|string $code,
        TemplateSnippetTenantVO|TenantRef $tenant,
        TemplateSnippetContentHtmlVO|string $contentHtml,
        TemplateSnippetEnabledVO|bool|null $enabled = null,
        TemplateSnippetVersionVO|int|null $version = null,
    ) {
        parent::__construct($uid);
        $this->_code = TemplateSnippetCodeVO::from($code);
        $this->_tenant = TemplateSnippetTenantVO::from($tenant);
        $this->_contentHtml = TemplateSnippetContentHtmlVO::from($contentHtml);
        $this->_enabled = null === $enabled ? TemplateSnippetEnabledVO::empty() : TemplateSnippetEnabledVO::from($enabled);
        $this->_version = null === $version ? TemplateSnippetVersionVO::empty() : TemplateSnippetVersionVO::from($version);
    }
    public function replace(TemplateSnippetAttributes $values): TemplateSnippet
    {
        $value = clone $this;
        $value->_code = $values->getCodeOrDefault($this->_code);
        $value->_tenant = $values->getTenantOrDefault($this->_tenant);
        $value->_contentHtml = $values->getContentHtmlOrDefault($this->_contentHtml);
        $value->_enabled = $values->getEnabledOrDefault($this->_enabled);
        $value->_version = $values->getVersionOrDefault($this->_version);
        return $value;
    }
    public static function calculatedFields(): array
    {
        return [ 'enabled'];
    }
    public static function create(TemplateSnippetAttributes $values): TemplateSnippet
    {
        $calculated = clone $values;
        $calculated->enabled(EnabledCalculator::calculateEnabled());
        $value = $calculated->build();
        $value->recordedEvents[] = new TemplateSnippetCreateEvent($value);
        return $value;
    }
    public function update(TemplateSnippetAttributes $values): TemplateSnippet
    {
        $calculated = clone $values;
        $calculated->enabled(EnabledCalculator::calculateEnabled($this));
        $value = $this->replace($calculated);
        $value->recordedEvents[] = new TemplateSnippetUpdateEvent($value, $this);
        return $value;
    }
    public function delete(): TemplateSnippet
    {
        $value = clone $this;
        $value->recordedEvents[] = new TemplateSnippetDeleteEvent($value);
        return $value;
    }
    public function enable(): TemplateSnippet
    {
        $value = clone $this;
        $value->_enabled = TemplateSnippetEnabledVO::from(true);
        $value->recordedEvents[] = new TemplateSnippetEnableEvent($value, original: $this);
        return $value;
    }
    public function disable(): TemplateSnippet
    {
        $value = clone $this;
        $value->_enabled = TemplateSnippetEnabledVO::from(false);
        $value->recordedEvents[] = new TemplateSnippetDisableEvent($value, original: $this);
        return $value;
    }
    public function asPublicJson(): array
    {
        $data = [];
        $data['uid'] = $this->uid();
        $data['code'] = $this->getCode();
        $data['tenant'] = [ '$ref' => $this->getTenant()->uid() ];
        $data['contentHtml'] = $this->getContentHtml();
        $data['enabled'] = $this->isEnabled();
        $data['version'] = $this->getVersion();
        return $data;
    }
    public function toAttributes(): TemplateSnippetAttributes
    {
        return (new TemplateSnippetAttributes())
          ->uid($this->uid())
          ->code($this->_code)
          ->tenant($this->_tenant)
          ->contentHtml($this->_contentHtml)
          ->enabled($this->_enabled)
          ->version($this->_version);
    }
    public function getTheEvents(): array
    {
        return [...$this->recordedEvents];
    }
}
